    async (props, auth) => {
      const {
        question,
        description,
        answers,
        outcomeType,
        shouldAnswersSumToOne,
        addAnswersMode,
      } = props
      const includeAnswers =
        answers &&
        answers.length > 0 &&
        outcomeType &&
        ['MULTIPLE_CHOICE', 'POLL'].includes(outcomeType)
      const outcomeKey =
        outcomeType == 'MULTIPLE_CHOICE'
          ? shouldAnswersSumToOne
            ? 'DEPENDENT_MULTIPLE_CHOICE'
            : 'INDEPENDENT_MULTIPLE_CHOICE'
          : outcomeType

