import { HOUR_MS } from 'common/util/time'
import { promptClaude } from 'shared/helpers/claude'
import { APIHandler } from './helpers/endpoint'
import { rateLimitByUser } from './helpers/rate-limit'
// import { models, promptGemini } from 'shared/helpers/gemini'

export const generateConciseTitle: APIHandler<'generate-concise-title'> =
  rateLimitByUser(
    async (props) => {
      const { question } = props
      const system = `Make this prediction market question more concise while preserving its core meaning. Keep the same level of precision and specificity, but make it more concise.
Guidelines:
- Use declarative, active voice statements ending with question marks
- Use English words rather than symbols/notations, e.g. 'More than' instead of '>'
- Keep essential dates, numbers, and conditions
- Use active voice over passive voice: i.e. 'US sanctions China' instead of 'China sanctioned by US'
- Keep important distinctions between market types (date, numeric, multiple choice, and binary), i.e if the market is forecasting 'when' something might happen, keep that distinction
- Remove unnecessary words, phrases, notations, e.g. "will", etc.
- Keep it concise
- Do not return anything other than the active voice, concise title, unless the question is already concise and declarative, in which case return a blank string
- Do not suggest a longer title than the original. If you can't make it more concise, just return a blank string
- Do NOT introduce jargon, niche acronyms, or anything that makes the title shorter but also more confusing, i.e. 'SWE' for 'software engineer', or 'S&P breaker' for 'stock market circuit breaker'
- Keep personal markets personal, e.g. "Will I go to the gym this week?" should NOT be changed to impersonal forms like "Personal gym attendance this week"
- Don't change the meaning of the question: include important and relevant parts of the question:
  - i.e. 'announce' in 'announce a ceasefire in 2025' is important and distinct from 'ceasefire in 2025'

Example transformations:
"Will a ceasefire between Russia and Ukraine be declared within 90 days of Trump entering the office of the presidency?" => "Russia-Ukraine ceasefire in Trump's first 90 days?"
"Will the first AI model that saturates Humanity's Last Exam be employable as a software engineer?" => "1st AI model to saturate Humanity's Last Exam employable as a software engineer?"
"In early 2028, will an AI be able to generate a full high-quality movie to a prompt?" => "Full, high-quality AI movie generator by early 2028?"
"Will there be a US recession by EOY2025?" => "US recession by EOY2025?"
"Will the US sanction China as a response to their development and use of an AI model by 2026?" => "US sanctions China for AI development by EOY2025??"
"Will I go to the gym this week?" => "I go to the gym this week?"
"Will I get a girlfriend this year?" => "I get a girlfriend this year?"
"Will I think getting an art MFA was worth it?" => "I'll think getting an art MFA was worth it?"
"AI negatively affects US doctors financially by EOY2025?" => '' (no change - already active voice, concise, and declarative)
"Substack publications at 5M+ paid subscribers by 2025?" => '' (no change - already concise and declarative)
"'A Minecraft Movie' (2025) Rotten Tomatoes critics score?" => '' (no change - already concise and declarative)
`

      const prompt = `Question: "${question}"
Your concise version, without any other text or commentary:`

      const response = await promptClaude(prompt, {
        system,
      })
      // const response = await promptGemini(prompt, {
      //   model: models.flash,
      //   system,
      // })

      let trimmedResponse = response.trim()
      if (trimmedResponse.startsWith('"') && trimmedResponse.endsWith('"')) {
        trimmedResponse = trimmedResponse.slice(1, -1)
      }
      return {
        title:
          trimmedResponse === '""' || trimmedResponse === "''"
            ? ''
            : trimmedResponse,
      }
    },
    { maxCalls: 100, windowMs: HOUR_MS }
  )

import { APIHandler } from 'api/helpers/endpoint'
import {
  buildUserInterestsCache,
  userIdsToAverageTopicConversionScores,
} from 'shared/topic-interests'
import { createSupabaseDirectClient } from 'shared/supabase/init'
import { convertContractComment } from 'common/supabase/comments'
import { parseJsonContentToText } from 'common/util/parse'
import { getContractsDirect } from 'shared/supabase/contracts'
import { uniq } from 'lodash'
import { ContractComment } from 'common/comment'
import { rateLimitByUser } from './helpers/rate-limit'
import { promptGemini } from 'shared/helpers/gemini'

export const getBestComments: APIHandler<'get-best-comments'> = rateLimitByUser(
  async (props, auth) => {
    const { limit, ignoreContractIds } = props
    const userId = auth.uid
    const pg = createSupabaseDirectClient()
    const followedOnly = false
    //   await pg.one(
    //     `
    // select count(*) > 5 as followed_only
    // from user_follows
    // where user_id = $1`,
    //     [userId],
    //     (r) => r.followed_only
    //   )
    if (
      !Object.keys(userIdsToAverageTopicConversionScores[userId] ?? {}).length
    ) {
      await buildUserInterestsCache([userId])
    }

    let allComments: { comment: ContractComment; question: string }[]
    let commentsToReview: { comment: ContractComment; question: string }[] = []

    const introText = `
      I am a user of Manifold. Manifold is a prediction market platform where
      users place bets on current events, politics, tech, sports, AI, and more.
      I have some comments that I would like you to rank in order of descending quality.
      Evaluate quality based on their informativeness relevant to the question, cogent analysis, and optionally humor. 
    `
    const ignoreText = `
      Please ignore short, meme-y comments like:
      "Buy low, sell high", "Buy my bags", "what were y'all thinking?", just a link without any commentary, etc. 
      Also ignore housekeeping comments that are remotely similar, or along the same vein as lines like:
      "Add [such and such answer] @user",
      "This resolves [yes/no/n/a], because [x/y/z], etc",
      "How does [betting/other shares] work?",
      "What do you mean by [x/y/z] in your title?",
      "Odds down sharply on [x/y/z]"
      "I've improved the question by doing [x/y/z], what do you think now traders?",
      "Does anyone have evidence that this should resolve [yes/no]."
      "Extended close time",
      "How do you plan to [resolve/judge/etc.] this?",
      and any solo web links without additional commentary, etc.
    `
    if (followedOnly) {
      // Assuming getFollowedRecentComments is defined elsewhere
      commentsToReview = await pg.map(
        `
            select distinct on (cc.created_time) cc.data, c.question
            from contract_comments cc
                     join contracts c on cc.contract_id = c.id
                     join group_contracts gc on c.id = gc.contract_id
            where cc.created_time >= now() - interval '1 week'
              and cc.data ->> 'replyToCommentId' is null
              and cc.data ->> 'betId' is null
              and cc.data ->> 'answerOutcome' is null
              and c.close_time > now()
              and cc.user_id in (select follow_id
                                  from user_follows
                                  where user_id = $1)
              and ($2 is null or c.id not in ($2:list))
              and cc.comment_id not in (select comment_id
                                        from user_comment_view_events
                                        where user_id = $1)
            order by cc.created_time desc
            limit $3;
        `,
        [userId, ignoreContractIds?.length ? ignoreContractIds : null, 100],
        (row) => ({
          comment: convertContractComment(row.data),
          question: row.question,
        })
      )
      allComments = commentsToReview
    } else {
      const reviewLimit = 1000
      const interestedTopics = Object.entries(
        userIdsToAverageTopicConversionScores[userId]
      )
        .filter(([_, score]) => score > 0.5)
        .map(([groupId, _]) => groupId)

      allComments = await pg.map(
        `
            select distinct on (cc.created_time) cc.data, c.question
            from contract_comments cc
                     join contracts c on cc.contract_id = c.id
                     join group_contracts gc on c.id = gc.contract_id
            where cc.created_time >= now() - interval '1 week'
              and gc.group_id in (select unnest(array [$1]))
              and cc.data ->> 'replyToCommentId' is null
              and cc.data ->> 'betId' is null
              and cc.data ->> 'answerOutcome' is null
              and c.close_time > now()
              and cc.likes > 0
              and ($3 is null or c.id not in ($3:list))
              and cc.comment_id not in (select comment_id
                                        from user_comment_view_events
                                        where user_id = $2)
            order by cc.created_time desc
            limit $4;
        `,
        [
          interestedTopics,
          userId,
          ignoreContractIds?.length ? ignoreContractIds : null,
          reviewLimit,
        ],
        (row) => ({
          comment: convertContractComment(row.data),
          question: row.question,
        })
      )

      const batchSize = 25
      const totalBatches = Math.ceil(allComments.length / batchSize)

      const processBatch = async (batch: typeof allComments) => {
        const batchPrompt = `
          ${introText}
          ${ignoreText}
          \n
          ${batch
            .map(
              ({ question, comment }) => `
          ----
          Question: ${question}
          Comment ID: ${comment.id}
          Comment: ${parseJsonContentToText(comment.content)}
          ----
          `
            )
            .join('\n')}
          Please evaluate quality based on informativeness relevant to the question, cogent analysis, and optionally humor. 
          ${ignoreText}
          Pick the best comment that you think a user might want to read based on the quality of the information
          conveyed. Do NOT pick any comments that don't meet the minimum quality bar. 
          Only return to me the comment ID, (ie don't say here is my top comment, just give me the ID)
        `

        const batchMsgContent = await promptGemini(batchPrompt)
        const batchCommentIds = batchMsgContent
          ? batchMsgContent
              .split(',')
              .map((s: string) => s.trim())
              .map((s: string) => s.replace(',', ''))
          : []

        return batch.filter((c) => batchCommentIds.includes(c.comment.id))
      }

      const batchPromises = []
      for (let i = 0; i < totalBatches; i++) {
        const batch = allComments.slice(i * batchSize, (i + 1) * batchSize)
        batchPromises.push(processBatch(batch))
      }

      const batchResults = await Promise.all(batchPromises)
      commentsToReview = batchResults.flat().slice(0, 100)
    }

    const prompt = `
      ${introText}
      ${ignoreText}
      \n
      ${commentsToReview
        .map(
          ({ question, comment }) => `
      ----
      Question: ${question}
      Comment ID: ${comment.id}
      Comment: ${parseJsonContentToText(comment.content)}
      ----
      `
        )
        .join('\n')}
      Please evaluate quality based on informativeness relevant to the question, cogent analysis, and optionally humor. 
      ${ignoreText}
      Now, you don't have to respond with ${limit} if there aren't ${limit} good comments, only
      respond with the highest quality comments you see.
      So, what are the highest quality ~${limit} comment IDs separated by commas, in order
      of descending quality? (ie don't say here are my top comments, just give me the IDs)
    `
    const chosenComments = await promptGemini(prompt)
    const commentIds = chosenComments
      ? chosenComments
          .split(',')
          .map((s: string) => s.trim())
          .map((s: string) => s.replace(',', ''))
      : []

    const comments = allComments
      .filter((c) => commentIds.includes(c.comment.id))
      .map((c) => c.comment)
      .slice(0, limit)
    const contracts = await getContractsDirect(
      uniq(comments.map((c) => c.contractId)),
      pg
    )

    return {
      comments,
      contracts,
    }
  }
)

