        e.message
    )
    return undefined
  }
  log('Made embeddings for question', question)
  return response.data[0].embedding
}

const imagePrompt = (q: string) =>
  `Header image for a discussion thread about predicting "${q}". Do not include text.`

export const generateImage = async (q: string) => {
  const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
  const prompt = imagePrompt(q)

  return await openai.images
    .generate({
      model: 'dall-e-3',
      prompt,
      n: 1,
      size: '1792x1024',
      quality: 'standard',
    })
    .then((res) => res.data[0].url)
    .catch((err) => (console.log(err), undefined))
}

const defaultOptions: {
  system?: string
  model: (typeof models)[keyof typeof models]
  reasoning?: { effort: 'low' | 'medium' | 'high' }
  webSearch?: boolean
} = {
  model: models.gpt5,
}

export const promptOpenAI = async (
  prompt: string,
  options: typeof defaultOptions = defaultOptions
) => {
  const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })

  const { system, model, reasoning, webSearch } = options

  const result = await openai.responses
    .create({
      model,
      input: prompt,
      ...(system ? { instructions: system } : {}),
      ...(webSearch
        ? {
            tools: [
              {
                type: 'web_search_preview_2025_03_11',
                search_context_size: 'high',
              },
            ],
            tool_choice: 'auto',
          }
        : {}),
      ...(reasoning ? { reasoning: { effort: reasoning.effort } } : {}),
      text: {
        // @ts-expect-error - verbosity is not typed
        verbosity: 'low',
      },
    })
    .catch((err) => (console.log(err), undefined))

  if (!result) throw new APIError(500, 'No result from OpenAI')

  const message = (result as any).output_text as string | undefined
  log('OpenAI Responses returned message:', message)
  if (!message) throw new APIError(500, 'No result from OpenAI')
  return message
}

export const promptOpenAIParsingAsJson = async (
  prompt: string,
  options: typeof defaultOptions = defaultOptions
) => {
  const res = await promptOpenAI(prompt, options)
  return parseAIResponseAsJson(res)
}

export const removeJsonTicksFromResponse = (response: string): string => {
  // Remove markdown code block formatting if present
  const jsonBlockRegex = /```(?:json)?\s*([\s\S]*?)```/
  const match = response.match(jsonBlockRegex)

  if (match && match[1]) {
    return match[1].trim()
  }

  // If no markdown formatting found, return the original response
  return response.trim()
}

export const promptOpenAIWebSearchParseJson = async <T>(
  prompt: string,
  options: typeof defaultOptions = defaultOptions
): Promise<T> => {
  const response = await promptOpenAI(prompt, { ...options, webSearch: true })
  return parseAIResponseAsJson(response)
}

import { models as claudeModels, promptClaude } from './claude'
import {
  models as geminiModels,
  parseAIResponseAsJson,
  promptGemini,
} from './gemini'
import { models as openaiModels, promptOpenAI } from './openai-utils'

type ReasoningEffort = 'low' | 'medium' | 'high'

export const aiModels = {
  ...openaiModels,
  ...claudeModels,
  ...geminiModels,
} as const

export type PromptAIOptionsBase = {
  model: (typeof aiModels)[keyof typeof aiModels]
  system?: string
  webSearch?: boolean
  reasoning?: { effort: ReasoningEffort }
}

export type PromptAIJsonOptions = PromptAIOptionsBase & { parseAsJson: true }
export type PromptAIStringOptions = PromptAIOptionsBase & {
  parseAsJson?: false
}

function getProviderFromModel(
  model: (typeof aiModels)[keyof typeof aiModels]
): 'openai' | 'claude' | 'gemini' {
  const lower = model.toLowerCase()
  if (lower.startsWith('claude')) return 'claude'
  if (lower.startsWith('gemini')) return 'gemini'
  return 'openai'
}

export async function promptAI<T>(
  prompt: string,
  options: PromptAIJsonOptions
): Promise<T>
export async function promptAI(
  prompt: string,
  options: PromptAIStringOptions
): Promise<string>
export async function promptAI<T = unknown>(
  prompt: string,
  options: (PromptAIJsonOptions | PromptAIStringOptions) & {
    model: (typeof aiModels)[keyof typeof aiModels]
  }
): Promise<string | T> {
  const { model, system, webSearch, reasoning } = options
  const provider = getProviderFromModel(model)

  let rawResponse: string

  if (provider === 'openai') {
    rawResponse = await promptOpenAI(prompt, {
      model: model as any,
      system,
      reasoning,
      webSearch,
    })
  } else if (provider === 'claude') {
    rawResponse = await promptClaude(prompt, { model: model as any, system })
  } else {
    rawResponse = await promptGemini(prompt, { model: model as any, system })
  }

  if ('parseAsJson' in options && options.parseAsJson) {
    return parseAIResponseAsJson(rawResponse) as T
  }
  return rawResponse
}

