          disabled={
            !question ||
            isGeneratingRanges ||
            min === undefined ||
            max === undefined ||
            minMaxError ||
            !unit
          }
        >
          {answers.length > 0 ? 'Regenerate ranges' : 'Generate ranges'}
        </Button>
      </Row>
      {error && (
        <div className="text-scarlet-500 mb-2 mt-2 text-sm">{error}</div>
      )}

      <ControlledTabs
        activeIndex={titles.indexOf(selectedTab)}
