      { name: 'Leagues', href: '/leagues', icon: TrophyIcon },
      {
        name: 'Forum',
        href: '/posts',
        icon: ChatIcon,
      },

      options.isAdminOrMod && {
        name: 'Reports',
        href: '/reports',
        icon: ReportsIcon,
      }
    )

  return buildArray(
