  )
}

const getMobileNav = (
  toggleModal: () => void,
  options: { isNewUser: boolean; isLiveTV?: boolean; isAdminOrMod: boolean }
) => {
  const { isAdminOrMod } = options

  return buildArray<NavItem>(
    { name: 'Leagues', href: '/leagues', icon: TrophyIcon },
    {
      name: 'Share with friends',
      href: '/referrals',
      icon: StarIcon,
    },
