  toggleTheme: () => void,
  router: AppRouterInstance,
  isMobile: boolean | undefined
) =>
  buildArray<NavItem>(
    loggedIn && { name: 'About', href: '/about', icon: QuestionMarkCircleIcon },
    !isMobile && {
      name: 'Share with friends',
      href: '/referrals',
      icon: StarIcon,
    },
    {
      name: theme ?? 'auto',
