  // Define columns for ContractRow, similar to how ContractsTable did
  const contractDisplayColumns = buildArray([
    !hasBets && boostedColumn,
    traderColumn,
    liquidityColumn,
    probColumn,
    !hideActions && actionColumn,
  ])

  return (
    <>
      {combinedItems.map((item) => {
        if (isContract(item)) {
          return (
            <ContractRow
              key={item.id as Key}
              contract={item}
              onClick={
                onContractClick ? () => onContractClick(item) : undefined
              }
              highlighted={highlightContractIds?.includes(item.id)}
              answers={answersByContractId?.[item.id]}
              hideAvatar={hideAvatars}
              columns={contractDisplayColumns} // Pass the defined columns
              showPosition={hasBets}
            />
          )
        } else if (isPost(item)) {
          return (
            <PostRow
              key={item.id as Key}
              post={item}
              highlighted={highlightContractIds?.includes(item.id)} // Assuming posts can also be highlighted by ID
              hideAvatar={hideAvatars}
            />
          )
        }
        return null // Should not be reached if type guards are exhaustive
      })}
    </>
  )
}

import { log } from 'shared/utils'

export const normalizeHyphens = (text: string) => {
  return text.replace(/[-−–—]/g, '')
}

export const constructPrefixTsQuery = (term: string) => {
  const sanitized = term
    .replace(/'/g, "''")
    .replace(/[!&|():*<>]/g, '')
    .trim()
  log(`Term: "${sanitized}"`)
  if (sanitized === '') return ''
  const tokens = sanitized.split(/\s+/)
  return tokens.join(' & ') + ':*'
}

export const constructPrefixTsQueryNormalized = (term: string) => {
  const normalizedTerm = normalizeHyphens(term)
  const sanitized = normalizedTerm
    .replace(/'/g, "''")
    .replace(/[!&|():*<>]/g, '')
    .trim()
  log(`Normalized term: "${sanitized}"`)
  if (sanitized === '') return ''
  const tokens = sanitized.split(/\s+/)
  return tokens.join(' & ') + ':*'
}

export const constructIlikeQuery = (term: string) => {
  const sanitized = term
    .replace(/'/g, "''")
    .replace(/[_%()<>]/g, '')
    .trim()

  if (sanitized === '') return ''
  return '%' + sanitized + '%' // ideally we'd do prefix but many groups have leading emojis
}

