} from 'lodash'
import { memo, useEffect, useMemo, useReducer, useRef, useState } from 'react'
import clsx from 'clsx'
import { ChevronDownIcon, ChevronUpIcon } from '@heroicons/react/solid'

import { Answer } from 'common/answer'
import {
