.touch-scale-down {
  transform: scale(0.95);
  transition: transform 0.1s ease-in-out;
}

/* Combined effect: bounce then hold */
@keyframes touch-press-bounce {
  0% {
    transform: scale(1);
  }
  25% {
    transform: scale(0.92);
  }
  50% {
    transform: scale(0.97);
  }
  100% {
