                        className={linkClass}
                      >
                        changelog page
                      </Link>
                      )
                    </span>
                  </Row>
                </>
              )}
              <Row className="items-center gap-2 px-1 py-2">
                <ShortToggle
                  on={postVisibility === 'public'}
                  setOn={(on) => setPostVisibility(on ? 'public' : 'unlisted')}
