// A txn (pronounced "texan") respresents a payment between two ids on Manifold
// Shortened from "transaction" to distinguish from Firebase transactions (and save chars)

import { QuestType } from 'common/quest'
import { league_user_info } from './leagues'

type AnyTxnType =
  | Donation
  | Tip
  | LootBoxPurchase
  | AdminReward
  | Manalink
  | Referral
  | UniqueBettorBonus
  | BettingStreakBonus
  | CancelUniqueBettorBonus
  | CharityFee
  | ManaPurchase
  | SignupBonus
  | ContractOldResolutionPayout
  | ContractProduceSpice
  | ContractUndoProduceSpice
  | ConsumeSpice
  | ConsumeSpiceDone
  | ConvertCash
  | ConvertCashDone
  | QfPayment
  | QfAddPool
  | QfDividend
  | PostAdCreate
  | PostAdRedeem
  | MarketAdCreate
  | MarketAdRedeem
  | MarketAdRedeemFee
  | QuestReward
  | QAndACreate
  | QAndAAward
  | LeaguePrize
  | BountyPosted
  | BountyAwarded
  | BountyAdded
  | BountyCanceled
  | ManaPay
  | Loan
  | PushNotificationBonus
  | LikePurchase
  | ContractUndoOldResolutionPayout
  | ContractAnte
  | AddSubsidy
  | RemoveSubsidy
  | ReclaimMana
  | ManachanTweet
  | BotCommentFee
  | AirDrop
  | ManifestAirDrop
  | ExtraPurchasedMana
  | ManifoldTopUp
  | CashBonus
  | CashOutPending
  | KycBonus
  | ProfitFee
  | UndoResolutionFee
  | ContractBoostPurchase

export type AnyTxnCategory = AnyTxnType['category']

export type SourceType = 'USER' | 'CONTRACT' | 'CHARITY' | 'BANK' | 'AD'

export type Txn<T extends AnyTxnType = AnyTxnType> = {
  id: string
  createdTime: number

  fromId: string
  fromType: SourceType

  toId: string
  toType: SourceType

  amount: number
  token: 'M$' | 'SHARE' | 'SPICE' | 'CASH' // if you add a new type, update the check in txn table schema

  category: AnyTxnType['category']

  /** Human-readable description. In data->>'description' in the db */
  description?: string

  /** Any extra data. For legacy reasons, in data->'data' in the db */
  data?: { [key: string]: any }
} & T

type LootBoxPurchase = {
  category: 'LOOTBOX_PURCHASE'
  fromType: 'USER'
  toType: 'BANK'
  token: 'M$'
}

type Donation = {
  fromType: 'USER'
  toType: 'CHARITY'
  category: 'CHARITY'
  token: 'SPICE' | 'M$' | 'CASH'
}

type Tip = {
  fromType: 'USER'
  toType: 'USER'
  category: 'TIP'
  data: {
    commentId: string
    contractId?: string
    groupId?: string
  }
}

type Manalink = {
  fromType: 'USER'
  toType: 'USER'
  category: 'MANALINK'
}

type Referral = {
  fromType: 'BANK'
  toType: 'USER'
  category: 'REFERRAL'
}

type UniqueBettorBonus = {
  fromType: 'BANK'
  toType: 'USER'
  category: 'UNIQUE_BETTOR_BONUS'
  data: {
    contractId: string
    uniqueNewBettorId?: string
    // Old unique bettor bonus txns stored all unique bettor ids
    uniqueBettorIds?: string[]
    isPartner: boolean
  }
}

type BettingStreakBonus = {
  fromType: 'BANK'
  toType: 'USER'
  category: 'BETTING_STREAK_BONUS'
  data: {
    currentBettingStreak?: number
    contractId?: string
  }
}

type CancelUniqueBettorBonus = {
  fromType: 'USER'
  toType: 'BANK'
  category: 'CANCEL_UNIQUE_BETTOR_BONUS'
  data: {
    contractId: string
  }
}

type CharityFee = {
  fromType: 'USER'
  toType: 'BANK'
  category: 'CHARITY_FEE'
  token: 'SPICE' | 'CASH'
  data: {
    charityId: string
  }
}

type ManaPurchase = {
  fromId: 'EXTERNAL'
  fromType: 'BANK'
  toType: 'USER'
  category: 'MANA_PURCHASE'
  data:
    | {
        iapTransactionId: string
        type: 'apple'
        // TODO: backfill this.
        paidInCents?: number
      }
    | {
        stripeTransactionId: string
        type: 'stripe'
        // TODO: backfill this.
        paidInCents?: number
      }
    | {
        transactionId: string
        type: 'gidx'
        sessionId: string
        paidInCents: number
      }
}
type CashBonus = {
  fromId: 'EXTERNAL'
  fromType: 'BANK'
  toType: 'USER'
  category: 'CASH_BONUS'
  data:
    | {
        transactionId: string
        type: 'gidx'
        sessionId: string
        paidInCents: number
      }
    | {
        iapTransactionId: string
        type: 'apple'
        paidInCents: number
      }
}

type CashOutPending = {
  fromType: 'USER'
  toType: 'BANK'
  token: 'CASH'
  category: 'CASH_OUT'
  data:
    | {
        sessionId: string
        transactionId: string
        type: 'gidx'
        payoutInDollars: number
      }
    | {
        merchantSessionId: string
        transactionId: string
        type: 'manual'
        payoutInDollars: number
      }
}

type KycBonus = {
  category: 'KYC_BONUS'
  fromType: 'BANK'
  toType: 'USER'
  token: 'CASH'
}

type SignupBonus = {
  fromType: 'BANK'
  toType: 'USER'
  category: 'SIGNUP_BONUS'
}

type ContractOldResolutionPayout = {
  fromType: 'CONTRACT'
  toType: 'USER'
  category: 'CONTRACT_RESOLUTION_PAYOUT'
  token: 'M$' | 'CASH'
  data: {
    /** @deprecated - we use CONTRACT_UNDO_RESOLUTION_PAYOUT **/
    reverted?: boolean
    deposit?: number
    payoutStartTime?: number
    answerId?: string
  }
}

// destroys mana in contract
type ContractProduceSpice = {
  fromType: 'CONTRACT'
  toType: 'USER'
  category: 'PRODUCE_SPICE'
  token: 'SPICE'
  data: {
    deposit?: number
    payoutStartTime?: number
    answerId?: string
  }
}

// these come in pairs to convert spice to mana
type ConsumeSpice = {
  fromType: 'USER'
  toType: 'BANK'
  category: 'CONSUME_SPICE'
  token: 'SPICE'
  data: {
    insertTime: number
  }
}
type ConsumeSpiceDone = {
  fromType: 'BANK'
  toType: 'USER'
  category: 'CONSUME_SPICE_DONE'
  token: 'M$'
  data: {
    insertTime: number
  }
}

