  editing: boolean
  setEditing: (isEditing: boolean) => void
}) {
  const { post, children, onUpdate, editing, setEditing } = props
  const user = useUser()
  const canEdit = user?.id === post.creatorId
  const [editableTitle, setEditableTitle] = useState(post.title)

  const editor = useTextEditor({
    defaultValue: post.content,
    key: `post ${post?.id || ''}`,
    size: 'lg',
  })

  return editing ? (
    <>
      <ExpandingInput
        value={editableTitle}
        onChange={(e) => setEditableTitle(e.target.value || '')}
        placeholder="Post title"
        className="mb-2 text-2xl font-bold"
      />
      <TextEditor editor={editor} />
      <Spacer h={2} />
      <Row className="gap-2">
        <Button
          color="gray"
          onClick={() => {
            setEditing(false)
            setEditableTitle(post.title)
            editor?.commands.focus('end')
          }}
        >
          Cancel
        </Button>
        <Button
          onClick={async () => {
            if (!editor) return
            const { post: updatedPost } = await api('update-post', {
              id: post.id,
              title: editableTitle,
              content: editor.getJSON(),
            })
            onUpdate?.(updatedPost)
            setEditing(false)
          }}
        >
          Save
        </Button>
      </Row>
    </>
  ) : (
    <Col className="gap-2">
      <Content size="lg" content={post.content} />
      {canEdit && (
        <Row className="place-content-end">
          <Button
            color="gray-white"
            size="xs"
            onClick={() => {
              setEditableTitle(post.title)
              setEditing(true)
              editor?.commands.focus('end')
            }}
          >
            <PencilIcon className="inline h-4 w-4" />
          </Button>
          {children}
        </Row>
      )}
    </Col>
  )
}

