              <span className="text-error">Insufficient balance</span>
              <Button
                size="xs"
                color="gradient-pink"
                onClick={() => setFundsModalOpen(true)}
              >
                Get mana
              </Button>
            </div>
          )}
        </Col>
      </Modal>

      <AddFundsModal open={fundsModalOpen} setOpen={setFundsModalOpen} />
    </>
  )
}

