  // TODO: Why not add this to front of bet queue?
  const {
    resolvedContract,
    updatedContractMetrics,
    payoutsWithoutLoans,
    updatedContractAttrs,
    userUpdates,
  } = await pg.tx({ mode: SERIAL_MODE }, async (tx) => {
