                <div className="text-ink-600 mt-1 text-base font-medium">
                  {formatPercent(topCompanies[1].probability)}
                </div>
                <div
                  className="w-full rounded-t-lg bg-blue-600 dark:bg-blue-300"
                  style={{
                    height: `${Math.max(
                      8,
