                    )}px`,
                  }}
                ></div>
              </div>

              {/* 1st Place - Middle */}
              <div className="w-[38%] text-center">
                {topCompanies[0].text ? (
                  <div className="flex flex-col items-center">
                    <div className="text-primary-600 mb-1 flex h-14 w-14 items-center justify-center sm:mb-2 sm:h-16 sm:w-16">
