                    height: `${Math.max(
                      8,
                      topCompanies[0].probability * 100
                    )}px`,
                  }}
                ></div>
              </div>

              {/* 3rd Place - Right */}
              <div className="w-[28%] text-center">
                {topCompanies[2].text ? (
