              </div>
            </div>
          </Col>
        </CardBase>
      )
    }

    return (
      <CardBase onClick={clickHandler} className={className}>
        <Col className="h-full space-y-1 sm:space-y-2">
          <div className="w-full">
            <CardTitle
              title={title}
